stable_1:MemoryRecordShape a sh:NodeShape ;
    sh:and ( [ sh:or ( [ sh:property [ sh:minCount 1 ;
                                    sh:path stable_1:contentHash ] ] [ sh:property [ sh:minCount 1 ;
                                    sh:path aegis:contentHash ] ] ) ] [ sh:or ( [ sh:property [ sh:minCount 1 ;
                                    sh:path stable_1:naturalKey ] ] [ sh:property [ sh:minCount 1 ;
                                    sh:path aegis:naturalKey ] ] ) ] [ sh:or ( [ sh:property [ sh:minCount 1 ;
                                    sh:path stable_1:recordedAt ] ] [ sh:property [ sh:minCount 1 ;
                                    sh:path aegis:recordedAt ] ] ) ] [ sh:or ( [ sh:property [ sh:minCount 1 ;
                                    sh:path stable_1:recordedBy ] ] [ sh:property [ sh:minCount 1 ;
                                    sh:path aegis:recordedBy ] ] ) ] [ sh:or ( [ sh:property [ sh:minCount 1 ;
                                    sh:path stable_1:sourceKind ] ] [ sh:property [ sh:minCount 1 ;
                                    sh:path aegis:sourceKind ] ] ) ] ) ;
    sh:property [ sh:description "Provenance tag: observed, declared or inferred; filled by the tool's sourceKind rule." ;
            sh:in _:cb2a3c14deeea6f3c01325a2917c28611e06b6d70426655c74c5120619f16d806b5 ;
            sh:maxCount 1 ;
            sh:message "Not recorded: the record needs exactly one sourceKind of observed, declared or inferred." ;
            sh:name "sourceKind" ;
            sh:path stable_1:sourceKind ],
        [ sh:description "Provenance tag: observed, declared or inferred; filled by the tool's sourceKind rule." ;
            sh:in _:cb2a3c14deeea6f3c01325a2917c28611e06b6d70426655c74c5120619f16d806b5 ;
            sh:maxCount 1 ;
            sh:message "Not recorded: the record needs exactly one sourceKind of observed, declared or inferred." ;
            sh:name "sourceKind" ;
            sh:path aegis:sourceKind ],
        [ sh:datatype xsd:dateTime ;
            sh:description "UTC instant the supersededBy link was written; the cursor bobbin's feed uses to drop the record." ;
            sh:maxCount 1 ;
            sh:message "Not recorded: a record is superseded once, at one UTC instant." ;
            sh:name "supersededAt" ;
            sh:path aegis:supersededAt ],
        [ sh:datatype xsd:dateTime ;
            sh:description "UTC instant the supersededBy link was written; the cursor bobbin's feed uses to drop the record." ;
            sh:maxCount 1 ;
            sh:message "Not recorded: a record is superseded once, at one UTC instant." ;
            sh:name "supersededAt" ;
            sh:path stable_1:supersededAt ],
        [ sh:description "The record's natural-key IRI (aegis:mem/<kind>/<scope>/<topic>); filled by the tool." ;
            sh:maxCount 1 ;
            sh:message "Not recorded: the record has no natural key (camayoc tool bug; report it)." ;
            sh:name "naturalKey" ;
            sh:nodeKind sh:IRI ;
            sh:path stable_1:naturalKey ],
        [ sh:datatype xsd:string ;
            sh:description "One-line label; filled by the tool from the record body." ;
            sh:maxCount 1 ;
            sh:message "Not recorded: the record has no label (camayoc tool bug; report it)." ;
            sh:minCount 1 ;
            sh:name "label" ;
            sh:path rdfs:label ],
        [ sh:description "The record's natural-key IRI (aegis:mem/<kind>/<scope>/<topic>); filled by the tool." ;
            sh:maxCount 1 ;
            sh:message "Not recorded: the record has no natural key (camayoc tool bug; report it)." ;
            sh:name "naturalKey" ;
            sh:nodeKind sh:IRI ;
            sh:path aegis:naturalKey ],
        [ sh:datatype xsd:dateTime ;
            sh:description "UTC instant the record was written; filled by the tool." ;
            sh:maxCount 1 ;
            sh:message "Not recorded: the record has no recordedAt instant (camayoc tool bug; report it)." ;
            sh:name "recordedAt" ;
            sh:path aegis:recordedAt ],
        [ sh:datatype xsd:dateTime ;
            sh:description "UTC instant the record was written; filled by the tool." ;
            sh:maxCount 1 ;
            sh:message "Not recorded: the record has no recordedAt instant (camayoc tool bug; report it)." ;
            sh:name "recordedAt" ;
            sh:path stable_1:recordedAt ],
        [ sh:datatype xsd:string ;
            sh:description "The agent that wrote the record ($SHANTY_AGENT or the harness agent id); filled by the tool." ;
            sh:maxCount 1 ;
            sh:message "Not recorded: the record does not say which agent wrote it; set SHANTY_AGENT." ;
            sh:name "recordedBy" ;
            sh:path aegis:recordedBy ],
        [ sh:datatype xsd:string ;
            sh:description "sha256 over the caller-supplied fields; how an unchanged re-record is detected." ;
            sh:maxCount 1 ;
            sh:message "Not recorded: the record has no content hash (camayoc tool bug; report it)." ;
            sh:name "contentHash" ;
            sh:path stable_1:contentHash ;
            sh:pattern "^sha256:[0-9a-f]{64}$" ],
        [ sh:datatype xsd:string ;
            sh:description "The agent that wrote the record ($SHANTY_AGENT or the harness agent id); filled by the tool." ;
            sh:maxCount 1 ;
            sh:message "Not recorded: the record does not say which agent wrote it; set SHANTY_AGENT." ;
            sh:name "recordedBy" ;
            sh:path stable_1:recordedBy ],
        [ sh:description "The earlier version this record replaces; filled by the tool on the same natural key." ;
            sh:maxCount 1 ;
            sh:message "Not recorded: a record supersedes at most one earlier version, by IRI." ;
            sh:name "supersedes" ;
            sh:nodeKind sh:IRI ;
            sh:path aegis:supersedes ],
        [ sh:datatype xsd:string ;
            sh:description "sha256 over the caller-supplied fields; how an unchanged re-record is detected." ;
            sh:maxCount 1 ;
            sh:message "Not recorded: the record has no content hash (camayoc tool bug; report it)." ;
            sh:name "contentHash" ;
            sh:path aegis:contentHash ;
            sh:pattern "^sha256:[0-9a-f]{64}$" ],
        [ sh:description "The earlier version this record replaces; filled by the tool on the same natural key." ;
            sh:maxCount 1 ;
            sh:message "Not recorded: a record supersedes at most one earlier version, by IRI." ;
            sh:name "supersedes" ;
            sh:nodeKind sh:IRI ;
            sh:path stable_1:supersedes ] ;
    sh:targetSubjectsOf aegis:naturalKey,
        stable_1:naturalKey .

stable_1:MemoryReferenceShape a sh:NodeShape ;
